DO $$ DECLARE v_form_id uuid; BEGIN
 SELECT id INTO v_form_id FROM public.dynamic_forms WHERE slug='funnel-eletro-solucoes-eficazes';
 IF v_form_id IS NULL THEN INSERT INTO public.dynamic_forms (slug,name,description,status,config_json,whatsapp_config) VALUES ('funnel-eletro-solucoes-eficazes','Orçamento · Eletro Soluções Eficazes','Funil individual para serviços elétricos e automação','published','{"auto_advance_ms":250}'::jsonb,'{"enabled":true}'::jsonb) RETURNING id INTO v_form_id; ELSE UPDATE public.dynamic_forms SET status='published',name='Orçamento · Eletro Soluções Eficazes' WHERE id=v_form_id; DELETE FROM public.dynamic_form_questions WHERE form_id=v_form_id; END IF;
 INSERT INTO public.dynamic_form_questions (form_id,key,type,label,order_index,required,options_json) VALUES
 (v_form_id,'welcome','statement','Vamos encontrar a solução ideal ⚡',0,false,'[]'::jsonb),(v_form_id,'nome','short_text','Qual é o seu nome?',1,true,'[]'::jsonb),(v_form_id,'servico','radio','Qual serviço você precisa?',2,true,jsonb_build_array(jsonb_build_object('value','instalacao','label','Instalação elétrica'),jsonb_build_object('value','iluminacao','label','Iluminação'),jsonb_build_object('value','manutencao','label','Manutenção elétrica'),jsonb_build_object('value','automacao','label','Automação residencial, predial ou industrial'),jsonb_build_object('value','projeto','label','Consultoria e projetos'))),(v_form_id,'projeto','radio','Onde será o serviço?',3,true,jsonb_build_array(jsonb_build_object('value','residencia','label','Residência'),jsonb_build_object('value','comercio','label','Comércio ou condomínio'),jsonb_build_object('value','industria','label','Empresa ou indústria'))),(v_form_id,'local','radio','Qual a cidade?',4,true,jsonb_build_array(jsonb_build_object('value','pinhais','label','Pinhais'),jsonb_build_object('value','curitiba','label','Curitiba e região'),jsonb_build_object('value','confirmar','label','Vou confirmar o endereço'))),(v_form_id,'detalhes','long_text','Mais detalhes','Fotos, medidas e objetivo ajudam na proposta.','Descreva seu projeto',5,false,'[]'::jsonb),(v_form_id,'telefone','phone','Qual WhatsApp para retorno?',6,true,'[]'::jsonb),(v_form_id,'confirmacao','statement','Solicitação recebida! ✅','A Eletro Soluções confirmará os próximos passos.',7,false,'[]'::jsonb); END $$;
